begin;
set local request.jwt.claims='{"aal":"aal2"}';select no_plan();
insert into auth.users(id,email) values('00000000-0000-4000-8000-000000001041','retention-owner@example.test');update public.profiles set role='admin' where id='00000000-0000-4000-8000-000000001041';
set local role authenticated;set local request.jwt.claim.sub='00000000-0000-4000-8000-000000001041';
select public.start_import_batch('00000000-0000-4000-8000-000000001040','customers','retention.csv',repeat('4',64),100,7);
select is((select extract(epoch from (file_expires_at-created_at))::integer/86400 from public.import_batches where id='00000000-0000-4000-8000-000000001040'),7,'retention configured at upload');
select throws_ok($$select public.start_import_batch(gen_random_uuid(),'customers','invalid.csv',repeat('5',64),100,0)$$,'23514','INVALID_RETENTION','retention lower bound');
select throws_ok($$select public.finish_import_file_retention('00000000-0000-4000-8000-000000001040')$$,'42501',null,'authenticated user cannot claim deletion');
insert into storage.objects(bucket_id,name,metadata) values('imports','00000000-0000-4000-8000-000000001040.csv','{"size":100}');
reset role;
update public.import_batches set file_expires_at=now()-interval '1 day',stats='{"rows":1}' where id='00000000-0000-4000-8000-000000001040';
insert into public.import_rows(batch_id,entity,sheet,row_number,raw,mapped,status) values('00000000-0000-4000-8000-000000001040','customers','Negozi',2,'{"unused":"source personal data"}','{"legal_name":"Historical synthetic"}','valid');
set local role authenticated;
select is((select count(*) from storage.objects where bucket_id='imports' and name='00000000-0000-4000-8000-000000001040.csv'),0::bigint,'expired original inaccessible before job runs');
reset role;set local request.jwt.claim.role='service_role';set local role service_role;
select throws_ok($$select public.finish_import_file_retention('00000000-0000-4000-8000-000000001040')$$,'23514','FILE_STILL_PRESENT','metadata not marked before storage deletion');
reset role;set local storage.allow_delete_query='true';delete from storage.objects where bucket_id='imports' and name='00000000-0000-4000-8000-000000001040.csv';set local storage.allow_delete_query='false';set local role service_role;
select ok(public.finish_import_file_retention('00000000-0000-4000-8000-000000001040'),'successful deletion recorded');
select ok(public.finish_import_file_retention('00000000-0000-4000-8000-000000001040'),'retention retry idempotent');
reset role;
select is((select raw from public.import_rows where batch_id='00000000-0000-4000-8000-000000001040'),'{}'::jsonb,'unused raw source cells discarded');
select is((select mapped->>'legal_name' from public.import_rows where batch_id='00000000-0000-4000-8000-000000001040'),'Historical synthetic','normalized data retained');
select is((select stats->>'rows' from public.import_batches where id='00000000-0000-4000-8000-000000001040'),'1','statistics retained');
select is((select status from public.import_batches where id='00000000-0000-4000-8000-000000001040'),'failed','expired unfinished upload cannot be resumed without original');
select * from finish();rollback;
